package com.smarthospital.controller;
import com.smarthospital.model.User;import com.smarthospital.util.*;import javax.servlet.*;import javax.servlet.http.*;import javax.servlet.annotation.*;import java.io.*;import java.sql.*;import java.util.*;
@WebServlet("/dashboard") public class DashboardServlet extends HttpServlet{
 protected void doGet(HttpServletRequest req,HttpServletResponse resp)throws ServletException,IOException{User u=(User)req.getSession().getAttribute("user");try(Connection c=DB.getConnection()){if(Access.isStaff(u))staff(c,req,u);else manager(c,req,u);req.getRequestDispatcher("/dashboard.jsp").forward(req,resp);}catch(Exception e){req.setAttribute("dbError",e.getMessage());req.getRequestDispatcher("/dashboard.jsp").forward(req,resp);}}
 private String scope(User u,String alias){return Access.isAdmin(u)?"1=1":alias+".department_id IN (SELECT department_id FROM supervisor_departments WHERE supervisor_user_id="+u.id()+" AND active=1)";}
 private void manager(Connection c,HttpServletRequest req,User u)throws Exception{req.setAttribute("dashboardRole",u.role());Map<String,Integer>m=new LinkedHashMap<>();if(Access.isAdmin(u)){m.put("Active staff",count(c,"SELECT COUNT(*) FROM staff WHERE status='ACTIVE'"));m.put("Active supervisors",count(c,"SELECT COUNT(*) FROM users WHERE role='SUPERVISOR' AND status='ACTIVE'"));m.put("Today's duties",count(c,"SELECT COUNT(*) FROM duties WHERE duty_date=CURDATE() AND status<>'CANCELLED'"));m.put("Open / unassigned",count(c,"SELECT COUNT(*) FROM duties WHERE status='OPEN'"));m.put("Proofs to review",count(c,"SELECT COUNT(*) FROM documents WHERE verification_status='PENDING'"));m.put("Approved leave today",count(c,"SELECT COUNT(*) FROM leaves WHERE status='APPROVED' AND CURDATE() BETWEEN start_date AND end_date"));}else{m.put("My department staff",count(c,"SELECT COUNT(*) FROM staff s WHERE s.status='ACTIVE' AND "+scope(u,"s")));m.put("Today's duties",count(c,"SELECT COUNT(*) FROM duties d WHERE d.duty_date=CURDATE() AND d.status<>'CANCELLED' AND "+scope(u,"d")));m.put("Open / unassigned",count(c,"SELECT COUNT(*) FROM duties d WHERE d.status='OPEN' AND "+scope(u,"d")));m.put("Proofs to review",count(c,"SELECT COUNT(*) FROM documents doc JOIN staff s ON doc.staff_id=s.staff_id WHERE doc.verification_status='PENDING' AND "+scope(u,"s")));m.put("Pending leave",count(c,"SELECT COUNT(*) FROM leaves l JOIN staff s ON l.staff_id=s.staff_id WHERE l.status='PENDING' AND "+scope(u,"s")));m.put("Completed today",count(c,"SELECT COUNT(*) FROM duty_assignments da JOIN duties d ON da.duty_id=d.duty_id WHERE da.status='COMPLETED' AND d.duty_date=CURDATE() AND "+scope(u,"d")));}req.setAttribute("stats",m);req.setAttribute("recent",recent(c,u));req.setAttribute("pendingProofs",pendingProofs(c,u));}
 private void staff(Connection c,HttpServletRequest req,User u)throws Exception{req.setAttribute("dashboardRole","STAFF");int sid=Access.ownStaffId(c,u.id());Map<String,Integer>m=new LinkedHashMap<>();
  m.put("Today's assignments",count(c,"SELECT COUNT(*) FROM duty_assignments da JOIN duties d ON da.duty_id=d.duty_id WHERE da.staff_id="+sid+" AND d.duty_date=CURDATE() AND da.status<>'CANCELLED'"));
  m.put("Upcoming assignments",count(c,"SELECT COUNT(*) FROM duty_assignments da JOIN duties d ON da.duty_id=d.duty_id WHERE da.staff_id="+sid+" AND d.duty_date>CURDATE() AND da.status NOT IN ('COMPLETED','CANCELLED')"));
  m.put("In progress",count(c,"SELECT COUNT(*) FROM duty_assignments WHERE staff_id="+sid+" AND status='IN_PROGRESS'"));
  m.put("Proofs awaiting review",count(c,"SELECT COUNT(*) FROM documents WHERE staff_id="+sid+" AND verification_status='PENDING'"));
  m.put("Completed duties",count(c,"SELECT COUNT(*) FROM duty_assignments WHERE staff_id="+sid+" AND status='COMPLETED'"));
  m.put("Unread notifications",count(c,"SELECT COUNT(*) FROM notifications WHERE user_id="+u.id()+" AND status='UNREAD'"));
  req.setAttribute("stats",m);req.setAttribute("recent",staffRecent(c,sid));req.setAttribute("pendingProofs",Collections.emptyList());req.setAttribute("nextDuty",nextDuty(c,sid));
 }
 private int count(Connection c,String q)throws Exception{try(Statement s=c.createStatement();ResultSet r=s.executeQuery(q)){r.next();return r.getInt(1);}}
 private List<Map<String,Object>> recent(Connection c,User u)throws Exception{List<Map<String,Object>>l=new ArrayList<>();String q="SELECT d.duty_name,d.duty_date,d.start_time,d.end_time,d.priority,d.status,dp.department_name,COALESCE(GROUP_CONCAT(s.name SEPARATOR ', '),'Unassigned') FROM duties d JOIN departments dp ON d.department_id=dp.department_id LEFT JOIN duty_assignments da ON d.duty_id=da.duty_id AND da.status<>'CANCELLED' LEFT JOIN staff s ON da.staff_id=s.staff_id WHERE "+scope(u,"d")+" GROUP BY d.duty_id ORDER BY (d.duty_date>=CURDATE()) DESC,d.duty_date ASC,d.start_time ASC LIMIT 8";try(Statement st=c.createStatement();ResultSet r=st.executeQuery(q)){while(r.next()){Map<String,Object>x=new HashMap<>();x.put("name",r.getString(1));x.put("date",r.getDate(2));x.put("start",r.getTime(3));x.put("end",r.getTime(4));x.put("priority",r.getString(5));x.put("status",r.getString(6));x.put("dept",r.getString(7));x.put("staff",r.getString(8));l.add(x);}}return l;}
 private List<Map<String,Object>> staffRecent(Connection c,int sid)throws Exception{List<Map<String,Object>>l=new ArrayList<>();String q="SELECT d.duty_name,d.duty_date,d.start_time,d.end_time,d.priority,da.status,dp.department_name FROM duty_assignments da JOIN duties d ON da.duty_id=d.duty_id JOIN departments dp ON d.department_id=dp.department_id WHERE da.staff_id=? ORDER BY CASE WHEN d.duty_date>=CURDATE() THEN 0 ELSE 1 END,d.duty_date ASC,d.start_time ASC LIMIT 8";try(PreparedStatement p=c.prepareStatement(q)){p.setInt(1,sid);try(ResultSet r=p.executeQuery()){while(r.next()){Map<String,Object>x=new HashMap<>();x.put("name",r.getString(1));x.put("date",r.getDate(2));x.put("start",r.getTime(3));x.put("end",r.getTime(4));x.put("priority",r.getString(5));x.put("status",r.getString(6));x.put("dept",r.getString(7));x.put("staff","My assignment");l.add(x);}}}return l;}
 private Map<String,Object> nextDuty(Connection c,int sid)throws Exception{String q="SELECT d.duty_id,d.duty_name,d.duty_date,d.start_time,d.end_time,d.priority,da.status,dp.department_name FROM duty_assignments da JOIN duties d ON da.duty_id=d.duty_id JOIN departments dp ON d.department_id=dp.department_id WHERE da.staff_id=? AND da.status NOT IN ('COMPLETED','CANCELLED') AND d.duty_date>=CURDATE() ORDER BY d.duty_date ASC,d.start_time ASC LIMIT 1";try(PreparedStatement p=c.prepareStatement(q)){p.setInt(1,sid);try(ResultSet r=p.executeQuery()){if(!r.next())return null;Map<String,Object>x=new LinkedHashMap<>();x.put("id",r.getInt(1));x.put("name",r.getString(2));x.put("date",r.getDate(3));x.put("start",r.getTime(4));x.put("end",r.getTime(5));x.put("priority",r.getString(6));x.put("status",r.getString(7));x.put("dept",r.getString(8));return x;}}}
 private List<Map<String,Object>> pendingProofs(Connection c,User u)throws Exception{List<Map<String,Object>>l=new ArrayList<>();String q="SELECT doc.document_id,s.name,d.duty_name,doc.file_name,doc.uploaded_at FROM documents doc JOIN staff s ON doc.staff_id=s.staff_id LEFT JOIN duties d ON doc.duty_id=d.duty_id WHERE doc.verification_status='PENDING' AND "+scope(u,"s")+" ORDER BY doc.uploaded_at DESC LIMIT 6";try(Statement st=c.createStatement();ResultSet r=st.executeQuery(q)){while(r.next()){Map<String,Object>x=new HashMap<>();x.put("id",r.getInt(1));x.put("staff",r.getString(2));x.put("duty",r.getString(3));x.put("file",r.getString(4));x.put("date",r.getTimestamp(5));l.add(x);}}return l;}
}
